/**
 * Path-based router for the Motivation PWA.
 * Leans heavily on the Navigation API (supported on all target devices).
 */

export interface RouteContext {
    path: string;
    params: Record<string, string>;
    query: URLSearchParams;
}

export interface RouteConfig {
    render: (ctx: RouteContext) => HTMLElement | Promise<HTMLElement>;
    /**
     * Story 291: the route one level up the tree, written as a route pattern.
     * `:name` segments resolve from the *current* route's matched params, so
     * `/health/log/new/:date/:slot` declares `/health/day/:date` and lands
     * on the concrete day. `/` is the only route without a parent.
     *
     * This is what makes the hierarchy a real thing the router can read rather
     * than something inferred from string prefixes at transition time.
     */
    parent?: string;
    /**
     * Story 291: marks this route as a step in a multi-screen task.
     * `exitFlow()` pops every contiguous entry carrying the same tag, so a
     * finished task leaves nothing on the back stack. The tag lives on the
     * route rather than at the call site — a screen joins the flow where it is
     * declared, not where somebody remembers to extend an array.
     */
    flow?: string;
}

/**
 * The active route table. `exitFlow` and the parent-chain helpers have to read
 * `flow` / `parent` off the route behind an arbitrary history entry, which no
 * call site can supply. One router owns one outlet, so a module-level handle is
 * the honest shape rather than a shortcut.
 */
let activeRoutes: Record<string, RouteConfig> = {};

// ── Navigation helpers ──────────────────────────────────────────────────────

/**
 * Attach a rejection handler to BOTH promises of a NavigationResult.
 *
 * The Navigation API returns two promises (`committed` and `finished`) and
 * either can reject independently — e.g. after a long PWA suspension Chrome
 * may discard the underlying session-history entry, in which case `back()` /
 * `traverseTo()` reject both with `InvalidStateError: Invalid key`. Catching
 * only `finished` leaves `committed`'s rejection to surface as an unhandled
 * promise rejection.
 *
 * `onFail` runs at most once. Aborts (e.g. a competing navigation) are
 * ignored — they're a normal part of the API contract, not user-facing errors.
 */
function handleNavigationResult(
    result: { committed?: Promise<unknown>; finished?: Promise<unknown> },
    onFail: (err: unknown) => void,
): void {
    let handled = false;
    const handler = (err: unknown) => {
        if (handled) return;
        if (err instanceof DOMException && err.name === 'AbortError') return;
        handled = true;
        onFail(err);
    };
    result.committed?.catch(handler);
    result.finished?.catch(handler);
}

/**
 * Story 289: `silent` marks a navigation as a URL rewrite by the screen that is
 * already mounted — the active screen's own state changed and the URL has to
 * follow (the day screen's Activity/Nutrition tab). The router intercepts it
 * with a no-op instead of re-activating the route, so nothing is remounted.
 * It travels as Navigation-API `info` rather than through `history.replaceState`
 * so the router keeps owning what a URL change means.
 */
export interface NavigateOptions {
    history?: 'push' | 'replace';
    silent?: boolean;
}

const SILENT_NAVIGATION_INFO = { silent: true } as const;

function isSilentNavigation(event: NavigateEvent): boolean {
    const info: unknown = event.info;
    return typeof info === 'object' && info !== null && (info as { silent?: unknown }).silent === true;
}

/** `undefined` when there is nothing to say — the API then defaults `history` to `auto`. */
function navigationOptions(options?: NavigateOptions): NavigationNavigateOptions | undefined {
    if (!options?.history && !options?.silent) return undefined;
    const navigateOptions: NavigationNavigateOptions = {};
    if (options.history) navigateOptions.history = options.history;
    if (options.silent) navigateOptions.info = SILENT_NAVIGATION_INFO;
    return navigateOptions;
}

export function navigate(path: string, options?: NavigateOptions): void {
    void navigateAndWait(path, options);
}

/**
 * `navigate` plus the settle. Sequential `window.navigation.navigate` calls
 * abort each other — a competing navigation is a normal part of the API
 * contract, and `handleNavigationResult` deliberately swallows `AbortError` —
 * so anything building several entries in a row (story 293's ancestor seeding)
 * has to wait for each one to finish or it silently loses rungs.
 */
function navigateAndWait(path: string, options?: NavigateOptions): Promise<void> {
    const url = path.startsWith('/') ? path : `/${path}`;
    const result = window.navigation.navigate(url, navigationOptions(options));
    handleNavigationResult(result, (err) => {
        console.warn('[ROUTER] navigation failed', url, err);
    });
    return Promise.resolve(result.finished).then(() => undefined, () => undefined);
}

/**
 * Story 370: step back to the nearest entry that is not `path` — past every entry of it, not just
 * one — or replace with `fallbackPath` when there is none. A side trip from the meals editor
 * leaves its return (`/health/meals?addIngredient…`) above the editor's own entry, so a single
 * `goBack` after Save landed on the stale seeded editor, which re-seeded the draft just saved.
 */
export function goBackPast(path: string, fallbackPath: string): void {
    const entries = window.navigation.entries();
    const currentIdx = window.navigation.currentEntry?.index ?? -1;
    for (let i = currentIdx - 1; i >= 0; i--) {
        const url = entries[i]?.url;
        if (!url || normalizePath(new URL(url).pathname) === normalizePath(path)) continue;
        try {
            handleNavigationResult(window.navigation.traverseTo(entries[i].key), () => navigate(fallbackPath, { history: 'replace' }));
            return;
        } catch {
            break;
        }
    }
    navigate(fallbackPath, { history: 'replace' });
}

/**
 * Story 378: step back to `path` when it is the entry right below this one, else replace this
 * entry with `fallbackPath`. The activity hub is pushed from its day; replacing the hub with that
 * day stacked it twice, and Back from it landed on the same day again.
 */
export function returnTo(path: string, fallbackPath: string): void {
    const index = window.navigation.currentEntry?.index ?? -1;
    const previous = index > 0 ? window.navigation.entries()[index - 1] : undefined;
    if (previous?.url && normalizePath(new URL(previous.url).pathname) === normalizePath(path)) {
        try {
            handleNavigationResult(window.navigation.traverseTo(previous.key), () => navigate(fallbackPath, { history: 'replace' }));
            return;
        } catch {
            // A stale key: fall through to the replace.
        }
    }
    navigate(fallbackPath, { history: 'replace' });
}

export function goBack(fallbackPath = '/'): void {
    let result: { committed?: Promise<unknown>; finished?: Promise<unknown> };
    try {
        result = window.navigation.back();
    } catch (err) {
        // `back()` throws synchronously when there is no previous entry, or
        // when the previous entry's key is no longer valid.
        console.warn('[ROUTER] Back failed; going to', fallbackPath, err);
        navigate(fallbackPath, { history: 'replace' });
        return;
    }

    handleNavigationResult(result, (err) => {
        console.warn('[ROUTER] Back failed; going to', fallbackPath, err);
        navigate(fallbackPath, { history: 'replace' });
    });
}

/**
 * Story 381 (pwa-shell-11): the section header's ←. Back when there is somewhere to go back to;
 * otherwise up — to the route's declared parent, or the section root, never the page itself. A
 * landing page passed its own path, so a failed back (an entry discarded while suspended) was a
 * dead tap.
 */
export function goBackOrUp(sectionPath: string): void {
    const current = normalizePath(window.location.pathname);
    const { route, params } = matchRoute(current, activeRoutes);
    const up = resolveParent(route, params) ?? (normalizePath(sectionPath) !== current ? sectionPath : '/');
    goBack(up);
}

// ── The declared tree (story 291) ───────────────────────────────────────────

/** Substitute `:name` segments from `params`. `null` when one has no value. */
function fillPattern(pattern: string, params: Record<string, string>): string | null {
    const parts = pattern.split('/');
    for (let i = 0; i < parts.length; i++) {
        if (!parts[i].startsWith(':')) continue;
        const value = params[parts[i].slice(1)];
        if (value === undefined) return null;
        // Story 381 (pwa-shell-25): params are the URL's own segments, still encoded — the screens
        // decode them. Encoding here again turned `Late%20snack` into `Late%2520snack`.
        parts[i] = value;
    }
    return normalizePath(parts.join('/'));
}

/**
 * The concrete parent path of `route` under `params`, or `null` when the route
 * declares none or the parent names a param this route does not carry.
 */
export function resolveParent(
    route: string,
    params: Record<string, string>,
    routes: Record<string, RouteConfig> = activeRoutes,
): string | null {
    const pattern = routes[route]?.parent;
    if (!pattern) return null;
    return fillPattern(pattern, params);
}

/**
 * The declared ancestor *patterns* of `route`, nearest first, root last. Walks
 * patterns rather than concrete paths so an ancestor that cannot be resolved
 * (its `:name` is not in the current params) still yields its own parent — the
 * chain skips it instead of stopping at it.
 *
 * The `seen` guard means a mis-declared cycle stops rather than hangs; the real
 * table is checked for cycles by a unit test, where a bad declaration should
 * fail loudly.
 */
export function ancestorPatterns(
    route: string,
    routes: Record<string, RouteConfig> = activeRoutes,
): string[] {
    const chain: string[] = [];
    const seen = new Set<string>([route]);
    let current = routes[route]?.parent;
    while (current && !seen.has(current)) {
        seen.add(current);
        chain.push(current);
        current = routes[current]?.parent;
    }
    return chain;
}

/** Concrete ancestor paths, nearest first. Unresolvable ancestors are dropped. */
export function ancestorChain(
    route: string,
    params: Record<string, string>,
    routes: Record<string, RouteConfig> = activeRoutes,
): string[] {
    const chain: string[] = [];
    for (const pattern of ancestorPatterns(route, routes)) {
        const path = fillPattern(pattern, params);
        if (path) chain.push(path);
    }
    return chain;
}

/**
 * Land on `target` with its declared ancestors beneath it (story 293).
 *
 * A deep arrival has no stack: the service worker's `clients.openWindow` boots
 * the document straight at the notification's path, and a bookmark or shared
 * link does the same. Without this, back from a cold-started screen exits the
 * app immediately, and a notification tapped while the app is open returns you
 * to whatever unrelated section you had left behind. Seeding the parent chain is
 * the convention Android already teaches for a deep-linked notification.
 *
 * The ancestors are created as real history entries but marked `silent`, so no
 * intermediate screen mounts, fetches, or animates — only `target` activates.
 *
 * **Known limit**: the Navigation API cannot delete entries *behind* the current
 * one, so a warm arrival leaves the pre-existing session below the seeded root.
 * Back rests at `/` and a further press re-enters the old session rather than
 * closing the app. Doing better needs a full document reload, which on this app
 * means re-running cross-origin isolation and the OPFS claim.
 */
export async function arriveAt(target: string): Promise<void> {
    const url = new URL(target, window.location.origin);
    const path = normalizePath(url.pathname);
    const { route, params } = matchRoute(path, activeRoutes);
    // Nearest-first from `ancestorChain`; seeding needs root-first.
    const ordered = ancestorChain(route, params, activeRoutes).reverse();

    if (ordered.length === 0) {
        await navigateAndWait(path + url.search, { history: 'replace' });
        return;
    }

    // Replace the entry we are on: it is either the cold-start entry for the
    // target itself (re-pushed below) or the screen the user left by tapping a
    // notification. Discarding it is the point — that entry is exactly what
    // back should not return to.
    await navigateAndWait(ordered[0], { history: 'replace', silent: true });
    for (const ancestor of ordered.slice(1)) {
        await navigateAndWait(ancestor, { silent: true });
    }
    await navigateAndWait(path + url.search);
}

/** The `flow` tag of whichever route serves `path`, if any. */
function flowOfPath(path: string): string | undefined {
    const { route } = matchRoute(path, activeRoutes);
    return activeRoutes[route]?.flow;
}

/**
 * Leave a multi-screen task, removing every one of its entries from the back
 * stack (story 291). Replaces `popOutOfFlow`, whose flow definition lived as a
 * duplicated prefix array at two call sites — which is how `/health/estimates`
 * came to be in the add-food flow without being in either array.
 *
 * Traverses back to the nearest entry whose route carries a *different* `flow`
 * tag, then — if `target` is given and that entry is not already it — pushes
 * `target`, which truncates the flow entries above. `target` covers the case
 * where the destination is not already below the flow: accepting an estimate
 * wants the day screen, which is right there when the flow was entered in-app
 * and absent when it was entered from a notification.
 *
 * The traverse is marked `silent` when a push follows, so the intermediate
 * screen is never mounted just to be replaced a tick later.
 */
export async function exitFlow(target?: string): Promise<void> {
    const currentPath = normalizePath(window.location.pathname);
    const { route, params } = matchRoute(currentPath, activeRoutes);
    const fallback = target ?? resolveParent(route, params) ?? '/';
    const flow = activeRoutes[route]?.flow;

    // Not in a flow: there is nothing to pop, and a silent no-op would leave
    // the caller stuck on a screen it considers finished.
    if (!flow) {
        goBack(fallback);
        return;
    }

    const entries = window.navigation.entries();
    const currentIdx = window.navigation.currentEntry?.index ?? -1;
    const targetUrl = target === undefined ? null : new URL(target, window.location.origin);
    // A target that carries a query is a distinct destination — `/health/meals`
    // and `/health/meals?fromIngredients=…` are not the same screen, and
    // landing on the bare one would drop the instruction. A target without one
    // matches on path alone, so returning to a day that happens to be showing
    // `?tab=activity` does not stack a second day entry.
    const targetIdentity = targetUrl === null
        ? null
        : normalizePath(targetUrl.pathname) + targetUrl.search;

    for (let i = currentIdx - 1; i >= 0; i--) {
        const entry = entries[i];
        if (!entry?.url) continue;
        const entryUrl = new URL(entry.url);
        const path = normalizePath(entryUrl.pathname);
        if (flowOfPath(path) === flow) continue;

        const entryIdentity = targetUrl?.search ? path + entryUrl.search : path;
        const pushesTarget = targetIdentity !== null && targetIdentity !== entryIdentity;
        try {
            const result = window.navigation.traverseTo(
                entry.key,
                pushesTarget ? { info: SILENT_NAVIGATION_INFO } : undefined,
            );
            // Attach a catch to `committed` too so a stale-key rejection
            // doesn't escape as an unhandled rejection while we're awaiting
            // `finished`.
            result.committed?.catch(() => {});
            await result.finished;
        } catch {
            break;
        }
        if (pushesTarget) navigate(target!);
        return;
    }

    navigate(fallback, { history: 'replace' });
}

// ── Router ──────────────────────────────────────────────────────────────────

export function startRouter(
    routes: Record<string, RouteConfig>,
    target: HTMLElement,
): () => void {
    activeRoutes = routes;
    let currentRoute = '';
    let currentFullPath = '';
    let renderSequence = 0;
    let pendingStaleCleanup: (() => void) | null = null;

    async function activate(url: URL): Promise<void> {
        if (pendingStaleCleanup) {
            pendingStaleCleanup();
            pendingStaleCleanup = null;
        }

        const path = normalizePath(url.pathname);
        const query = new URLSearchParams(url.search);
        const { route, params } = matchRoute(path, routes);

        const fullPath = fullPathOf(url);
        if (route === '/' && path !== '/') {
            // Story 381 (pwa-shell-18): say so, and keep the URL — a silent redirect home hid a
            // push for a renamed route, or a broken link, behind the home screen.
            console.warn('[ROUTER] No route for', path);
            currentRoute = '';
            currentFullPath = fullPath;
            ++renderSequence;
            target.replaceChildren(buildNoRouteScreen(path));
            return;
        }

        if (fullPath === currentFullPath) return;

        const isBack = isBackNavigation(currentRoute, route, routes);
        currentRoute = route;
        currentFullPath = fullPath;

        if (isBack) {
            document.documentElement.classList.add('back-transition');
        } else {
            document.documentElement.classList.remove('back-transition');
        }

        const config = routes[route];
        if (!config) return;

        const activationId = ++renderSequence;
        const render = async () => {
            let screen: HTMLElement;
            try {
                screen = await config.render({ path, params, query });
                try {
                    sessionStorage.removeItem('stale_bundle_reloaded');
                } catch {
                    // Ignore storage errors
                }
            } catch (err) {
                // Story 381 (pwa-shell-08): the user has already moved on — its stale chunk must not
                // arm a reload under the screen they are on now.
                if (activationId !== renderSequence) {
                    console.warn('[ROUTER] A route left before it loaded failed:', path, err);
                    return;
                }
                if (looksLikeStaleBundle(err)) {
                    let alreadyReloaded = false;
                    try {
                        alreadyReloaded = sessionStorage.getItem('stale_bundle_reloaded') === 'true';
                    } catch {
                        // ignore
                    }

                    let reloadTimeout: ReturnType<typeof setTimeout> | null = null;
                    let countdownInterval: ReturnType<typeof setInterval> | null = null;

                    const cancelReload = () => {
                        if (reloadTimeout) clearTimeout(reloadTimeout);
                        if (countdownInterval) clearInterval(countdownInterval);
                    };

                    screen = buildStaleBundleScreen(path, {
                        alreadyReloaded,
                        onCancel: cancelReload
                    });

                    pendingStaleCleanup = cancelReload;

                    if (!alreadyReloaded) {
                        let secondsLeft = 5;
                        reloadTimeout = setTimeout(() => {
                            if (countdownInterval) clearInterval(countdownInterval);
                            try {
                                sessionStorage.setItem('stale_bundle_reloaded', 'true');
                            } catch {
                                // ignore
                            }
                            window.location.reload();
                        }, 5000);

                        const textEl = screen.querySelector('.stale-bundle__countdown-text');
                        if (textEl) {
                            countdownInterval = setInterval(() => {
                                secondsLeft--;
                                if (secondsLeft > 0) {
                                    textEl.textContent = `Refreshing automatically in ${secondsLeft} seconds... `;
                                } else {
                                    textEl.textContent = 'Refreshing...';
                                    if (countdownInterval) clearInterval(countdownInterval);
                                }
                            }, 1000);
                        }
                    }
                } else {
                    screen = buildRouteErrorScreen(path, err);
                }
            }
            if (activationId === renderSequence) {
                target.replaceChildren(screen);
            }
        };

        if (document.startViewTransition && document.visibilityState === 'visible') {
            try {
                await document.startViewTransition(render).finished;
            } catch {
                await render();
            }
        } else {
            await render();
        }
    }

    const onNavigate = (event: NavigateEvent) => {
        if (!event.canIntercept) return;
        const destination = new URL(event.destination.url);
        if (destination.origin !== window.location.origin) return;

        // A screen rewriting its own URL (story 289). Intercept so the browser
        // stays in-document, but skip activation entirely — only the router's
        // idea of where it is has to move, or the next real navigation to the
        // pre-rewrite URL would be treated as a no-op. Scroll stays manual and
        // un-called: the user is mid-page and nothing should jump.
        if (isSilentNavigation(event)) {
            currentFullPath = fullPathOf(destination);
            // Story 291: a silent *traverse* (exitFlow popping out before it
            // pushes) changes the route, not just the query — story 289's tab
            // rewrite only ever changed the latter. Keep `currentRoute` honest
            // too, or the push that follows computes its transition direction
            // against the screen we already left.
            currentRoute = matchRoute(normalizePath(destination.pathname), routes).route;
            event.intercept({ scroll: 'manual', handler: async () => {} });
            return;
        }

        event.intercept({
            scroll: 'manual',
            async handler() {
                await activate(destination);
                event.scroll();
            },
        });
    };

    window.navigation.addEventListener('navigate', onNavigate);

    // Story 293: a document that arrived deep with NO STACK — notification
    // openWindow, bookmark, shared link, typed URL in a fresh tab — gets its
    // declared ancestors seeded beneath it, so back climbs out through its own
    // section instead of exiting on the first press.
    //
    // "No stack" is `entries().length <= 1`, not merely "the path is deep". A
    // reload keeps the whole entry list, so `startRouter` runs again with the
    // ancestors already below — re-seeding there would stack a second `/` and
    // `/health` on top of them and send back to the section root instead of the
    // screen you came from. (Caught by the pre-existing nutrition- and
    // activity-edit reload tests, which is exactly what they are for.)
    const initialUrl = new URL(window.location.href);
    const initial = matchRoute(normalizePath(initialUrl.pathname), routes);
    const arrivedWithoutStack = window.navigation.entries().length <= 1;
    if (arrivedWithoutStack && ancestorChain(initial.route, initial.params, routes).length > 0) {
        void arriveAt(fullPathOf(initialUrl));
    } else {
        void activate(initialUrl);
    }

    return () => {
        if (pendingStaleCleanup) {
            pendingStaleCleanup();
        }
        window.navigation.removeEventListener('navigate', onNavigate);
        activeRoutes = {};
    };
}

/** Story 381 (pwa-shell-18): an unknown path, said plainly — the raw path, not a guess at home. */
function buildNoRouteScreen(path: string): HTMLElement {
    const el = document.createElement('section');
    el.className = 'route-error';
    el.dataset.path = path;
    const heading = document.createElement('h2');
    heading.textContent = `No route for ${path}`;
    const home = document.createElement('a');
    home.href = '/';
    home.textContent = 'Home';
    el.append(heading, home);
    return el;
}

function buildRouteErrorScreen(path: string, err: unknown): HTMLElement {
    const message = err instanceof Error ? (err.stack ?? `${err.name}: ${err.message}`) : String(err);
    const el = document.createElement('section');
    el.className = 'route-error';
    el.dataset.path = path;

    const heading = document.createElement('h2');
    heading.textContent = `Failed to load ${path}`;
    el.appendChild(heading);

    const hint = document.createElement('p');
    hint.textContent = 'The route handler threw an error. Common cause: a dynamic import chunk is not cached and the network is offline.';
    el.appendChild(hint);

    const pre = document.createElement('pre');
    pre.className = 'route-error__stack';
    pre.textContent = message;
    el.appendChild(pre);

    const reload = document.createElement('button');
    reload.type = 'button';
    reload.textContent = 'Reload';
    reload.addEventListener('click', () => { window.location.reload(); });
    el.appendChild(reload);

    return el;
}

const STALE_BUNDLE_PATTERNS = [
    /Failed to fetch dynamically imported module/i, // Chrome
    /error loading dynamically imported module/i,   // Safari
    /Importing a module script failed/i,            // Firefox
];

function looksLikeStaleBundle(err: unknown): boolean {
    const msg = err instanceof Error ? err.message : String(err);
    return STALE_BUNDLE_PATTERNS.some((re) => re.test(msg));
}

function buildStaleBundleScreen(
    path: string, 
    options: { 
        alreadyReloaded: boolean; 
        onCancel: () => void; 
    }
): HTMLElement {
    const el = document.createElement('section');
    el.className = 'route-error stale-bundle';
    el.dataset.path = path;

    const heading = document.createElement('h2');
    heading.textContent = 'App updated — refresh to load the new version';
    el.appendChild(heading);

    const hint = document.createElement('p');
    hint.textContent = 'The application has been updated on the server. The section you requested needs the latest version of the app to load.';
    el.appendChild(hint);

    const countdownContainer = document.createElement('div');
    countdownContainer.className = 'stale-bundle__countdown-container';
    
    if (!options.alreadyReloaded) {
        const countdownText = document.createElement('span');
        countdownText.className = 'stale-bundle__countdown-text';
        countdownText.textContent = 'Refreshing automatically in 5 seconds... ';
        countdownContainer.appendChild(countdownText);

        const cancelBtn = document.createElement('button');
        cancelBtn.type = 'button';
        cancelBtn.className = 'stale-bundle__cancel';
        cancelBtn.textContent = 'Cancel';
        cancelBtn.addEventListener('click', () => {
            options.onCancel();
            countdownContainer.textContent = 'Auto-refresh cancelled.';
        });
        countdownContainer.appendChild(cancelBtn);
    } else {
        const warning = document.createElement('p');
        warning.className = 'stale-bundle__warning';
        warning.textContent = 'Note: We already tried to refresh automatically. If the issue persists, please check your network connection or try reloading manually.';
        countdownContainer.appendChild(warning);
    }
    
    el.appendChild(countdownContainer);

    const actions = document.createElement('div');
    actions.className = 'stale-bundle__actions';
    
    const refreshBtn = document.createElement('button');
    refreshBtn.type = 'button';
    refreshBtn.className = 'stale-bundle__refresh';
    refreshBtn.textContent = 'Refresh now';
    refreshBtn.addEventListener('click', () => {
        try {
            sessionStorage.setItem('stale_bundle_reloaded', 'true');
        } catch {
            // ignore
        }
        window.location.reload();
    });
    actions.appendChild(refreshBtn);
    
    el.appendChild(actions);

    return el;
}

// ── Internals ───────────────────────────────────────────────────────────────

export function matchRoute(
    pathname: string,
    routes: Record<string, RouteConfig>,
): { route: string; params: Record<string, string> } {
    const path = normalizePath(pathname);

    if (path === '/') return { route: '/', params: {} };
    if (routes[path]) return { route: path, params: {} };

    for (const pattern of Object.keys(routes)) {
        if (!pattern.includes(':')) continue;

        const patternParts = pattern.split('/');
        const pathParts = path.split('/');
        if (patternParts.length !== pathParts.length) continue;

        const params: Record<string, string> = {};
        let match = true;

        for (let i = 0; i < patternParts.length; i++) {
            if (patternParts[i].startsWith(':')) {
                if (!pathParts[i]) { match = false; break; }
                params[patternParts[i].substring(1)] = pathParts[i];
            } else if (patternParts[i] !== pathParts[i]) {
                match = false;
                break;
            }
        }

        if (match) return { route: pattern, params };
    }

    return { route: '/', params: {} };
}

/**
 * Story 291: back means "the destination is an ancestor", read off the declared
 * tree. The previous prefix test guessed from strings, so a genuine browser-back
 * between siblings animated forward while unrelated routes that happened to
 * share a prefix animated backward.
 */
function isBackNavigation(
    fromRoute: string,
    toRoute: string,
    routes: Record<string, RouteConfig>,
): boolean {
    if (!fromRoute || fromRoute === toRoute) return false;
    return ancestorPatterns(fromRoute, routes).includes(toRoute);
}

/** The router's identity for a URL: normalized path plus its query string. */
function fullPathOf(url: URL): string {
    const query = new URLSearchParams(url.search).toString();
    return `${normalizePath(url.pathname)}${query ? `?${query}` : ''}`;
}

function normalizePath(path: string): string {
    if (!path || path === '/') return '/';
    const p = path.startsWith('/') ? path : `/${path}`;
    return p.endsWith('/') ? p.slice(0, -1) : p;
}
